def classify(name):
    n=name.lower()
    for rx,c,sub,_ in EXTRA[:-1]:
        if re.search(rx,n):
            if sub=='TipDetaliKuzova': return c,sub,next((v for r2,v in BODY if re.search(r2,n)),'Кузов по частям')
            if sub=='EngineSparePartType': return c,sub,next((v for r2,v in ENG if re.search(r2,n)),'Электродвигатели и компоненты')
            return c,None,None
    for rx,c,sub in R:
        if re.search(rx,n):
            if sub=='B': return c,'TipDetaliKuzova',next((v for r2,v in BODY if re.search(r2,n)),'Кузов по частям')
            if sub=='E': return c,'EngineSparePartType',next((v for r2,v in ENG if re.search(r2,n)),'Электродвигатели и компоненты')
            if sub=='T': return c,'TransmissionSparePartType',next((v for r2,v in TRN if re.search(r2,n)),'Валы, муфты, шестерни и подшипники КПП')
            return c,None,None
    for rx,c,sub,_ in EXTRA:
        if re.search(rx,n):
            if sub=='TipDetaliKuzova': return c,sub,next((v for r2,v in BODY if re.search(r2,n)),'Кузов по частям')
            if sub=='EngineSparePartType': return c,sub,next((v for r2,v in ENG if re.search(r2,n)),'Электродвигатели и компоненты')
            return c,None,None
